new='''_LINKS = {
    "US/Pacific": "America/Los_Angeles", "US/Eastern": "America/New_York", "US/Central": "America/Chicago",
    "US/Mountain": "America/Denver", "Asia/Calcutta": "Asia/Kolkata", "Asia/Saigon": "Asia/Ho_Chi_Minh",
    "Europe/Kiev": "Europe/Kyiv", "America/Buenos_Aires": "America/Argentina/Buenos_Aires",
    "Brazil/East": "America/Sao_Paulo", "UTC": "Etc/UTC", "GMT": "Etc/UTC",
}
_LOCALES = ("en-US", "en-GB", "en-IN", "de-DE", "de-CH", "fr-FR", "pt-BR", "es", "ja-JP")
_ZERO = {"CLP", "ISK", "JPY", "KRW", "UGX", "VND"}
_THREE = {"BHD", "JOD", "KWD", "OMR", "TND"}
# locale -> (decimal, group, code_before)
_STYLE = {
    "en-US": (".", ",", True), "en-GB": (".", ",", True), "ja-JP": (".", ",", True), "en-IN": (".", ",", True),
    "pt-BR": (",", ".", True), "de-DE": (",", ".", False), "es": (",", ".", False),
    "de-CH": (".", "\\u2019", False), "fr-FR": (",", "\\u202f", False),
}


def _zone(tz: str) -> str:
    tz = tz.strip()
    m = re.fullmatch(r"(?:UTC|GMT)?\\s*([+-])(\\d{1,2})(?::?(\\d{2}))?", tz)
    if m and ("/" not in tz):
        hours = int(m.group(2))
        if hours == 0:
            return "Etc/UTC"
        return f"Etc/GMT{'-' if m.group(1) == '+' else '+'}{hours}"
    return _LINKS.get(tz, tz)


def _locale(loc: str) -> str:
    base = re.split(r"[.@]", loc)[0].replace("_", "-")
    parts = base.split("-")
    tag = parts[0].lower() + ("-" + parts[1].upper() if len(parts) > 1 and parts[1] else "")
    if tag in _LOCALES:
        return tag
    if parts[0].lower() in _LOCALES:
        return parts[0].lower()
    return "en-US"


def _digits(currency: str) -> int:
    return 0 if currency in _ZERO else 3 if currency in _THREE else 2


def _amount(value: str, digits: int) -> Decimal:
    return Decimal(value).quantize(Decimal(1).scaleb(-digits), rounding=ROUND_HALF_EVEN)


def _group(n: str, sep: str, indian: bool, ungroup4: bool) -> str:
    if ungroup4 and len(n) == 4:
        return n
    if len(n) <= 3:
        return n
    if indian:
        head, tail = n[:-3], n[-3:]
        out = []
        while len(head) > 2:
            out.insert(0, head[-2:])
            head = head[:-2]
        if head:
            out.insert(0, head)
        return sep.join(out + [tail])
    out = []
    while len(n) > 3:
        out.insert(0, n[-3:])
        n = n[:-3]
    return sep.join([n] + out)


def _format(value: Decimal, currency: str, locale: str) -> str:
    dec, grp, before = _STYLE[locale]
    digits = _digits(currency)
    value = value.quantize(Decimal(1).scaleb(-digits), rounding=ROUND_HALF_EVEN)
    neg = value < 0
    text = f"{abs(value):f}"
    ip, _, fp = text.partition(".")
    num = _group(ip, grp, locale == "en-IN", locale == "es")
    if digits:
        num += dec + fp.ljust(digits, "0")
    if neg:
        num = "-" + num
    nb = "\\u00a0"
    return f"{currency}{nb}{num}" if before else f"{num}{nb}{currency}"


def monthly_statement(transport: Transport, merchant: Merchant, year: int, month: int) -> Statement:
    """The statement of `merchant` for one calendar month, with its days in the merchant's time zone.

    One line per day that has settlements, in day order, with the figures and the text the
    Meridale dashboard shows. Raises ApiError when the API answers with an error.
    """
    first = date(year, month, 1)
    nxt = date(year + month // 12, month % 12 + 1, 1)
    locale = _locale(merchant.locale)
    params = {
        "merchant_id": merchant.id,
        "tz": _zone(merchant.tz),
        "from": first.isoformat(),
        "to": nxt.isoformat(),
        "locale": locale,
    }
    report = _call(transport, "GET", f"{BASE}/settlements", params)
    cur = report["currency"]
    digits = _digits(cur)
    lines = []
    for d in report["days"]:
        gross, fees, refunds = (_amount(d[k], digits) for k in ("gross", "fees", "refunds"))
        net = gross - fees - refunds
        lines.append(Line(date.fromisoformat(d["day"]), gross, fees, refunds, net, _format(net, cur, locale)))
    total = sum((line.net for line in lines), Decimal(0).scaleb(-digits))
    return Statement(merchant.id, cur, tuple(lines), total, _format(total, cur, locale))
'''
s=s[:i]+new
